'use strict';

var BigInt = require( '@stdlib/bigint/ctor' );
var xorshift128plus = require( './../lib' );
var match;
var valA;
var valB;

// Generate pseudorandom 64-bit integers...
console.log( '\n=== Pseudorandom 64-bit Integers ===' );
console.log( 'seed: %s', BigInt(12345) );

var rng = xorshift128plus({
	'seed': BigInt(12345)
});

var i;
for ( i = 0; i < 10; i++ ) {
	console.log( rng().toString() );
}

// Generate normalized random numbers in [0, 1)...
console.log( '\n=== Normalized Random Numbers [0, 1) ===' );

rng = xorshift128plus({
	'seed': BigInt(12345)
});

for ( i = 0; i < 10; i++ ) {
	console.log( rng.normalized() );
}

// Create a new pseudorandom number generator with a custom seed...
console.log( '\n=== Custom Seed ===' );

var seed = BigInt(54321);
var rand = xorshift128plus({
	'seed': seed
});

console.log( 'seed: %s', seed );
for ( i = 0; i < 10; i++ ) {
	console.log( rand().toString() );
}

// Create another pseudorandom number generator using a previous seed...
console.log( '\n=== Using Previous Seed ===' );

rand = xorshift128plus({
	'seed': BigInt(99999)
});
var previousSeed = rand.seed;

// Generate some values
for ( i = 0; i < 5; i++ ) {
	rand();
}

// Create a new generator with the previous seed
rand = xorshift128plus({
	'seed': previousSeed
});

console.log( 'seed: %s', previousSeed );
for ( i = 0; i < 10; i++ ) {
	console.log( rand().toString() );
}

// Demonstrate state management...
console.log( '\n=== State Management ===' );

var rng1 = xorshift128plus({
	'seed': BigInt(777)
});
console.log( 'Generated values: ' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', rng1().toString() );
}

// Save state
var state = rng1.state;
console.log( 'State saved' );

// Generate more values
console.log( 'Generated more values:' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', rng1().toString() );
}

// Restore state
rng1.state = state;
console.log( 'State restored' );

// Generate the same values as before
console.log( 'Same values regenerated:' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', rng1().toString() );
}

// Demonstrate generator copying...
console.log( '\n=== Generator Copying ===' );

var original = xorshift128plus({
	'seed': BigInt(555)
});
console.log( 'Original generator:' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', original().toString() );
}

var copy = original.copy();
console.log( 'Copied generator (should produce same sequence):' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', copy().toString() );
}

// Now they diverge
console.log( 'Original continues:' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', original().toString() );
}

console.log( 'Copy continues (different):' );
for ( i = 0; i < 5; i++ ) {
	console.log( '  %s', copy().toString() );
}

// Demonstrate reproducibility...
console.log( '\n=== Reproducibility ===' );

var rngA = xorshift128plus({
	'seed': BigInt(888)
});
var rngB = xorshift128plus({
	'seed': BigInt(888)
});

console.log( 'Both generators with same seed produce identical sequences:' );
for ( i = 0; i < 10; i++ ) {
	valA = rngA();
	valB = rngB();
	match = ( valA === valB ) ? '✓' : '✗';
	console.log( '  %s  %s === %s', match, valA.toString(), valB.toString() );
}

// Demonstrate JSON serialization...
console.log( '\n=== JSON Serialization ===' );

var jsonRng = xorshift128plus({
	'seed': BigInt(333)
});
var json = jsonRng.toJSON();

console.log( 'Serialized state:' );
console.log( '  type: %s', json.type );
console.log( '  name: %s', json.name );
console.log( '  state length: %d', json.state.length );
console.log( 'Full JSON object:' );
console.log( json );
